"""Test data of the effect tests (agent A6), run from the repository root.

  python apps/PaintCraft/tests/fixtures/make_a6.py                 a6_photo.png
  python apps/PaintCraft/tests/fixtures/make_a6.py --hash FX k=v   efftest reference hash of FX
  python apps/PaintCraft/tests/fixtures/make_a6.py --fx-all        regenerate tests/fx_all.uis

a6_photo.png  320 x 240 RGBA: colour gradients, a noise texture, a white disc, a dark bar and a
              half transparent band (alpha 128) with a fully transparent hole -- deterministic.
Reference hashes = FNV-1a 64 over the rows (w * 4 bytes B, G, R, A) of efftest's result
(`efftest --shot - --in a6_photo.png --out x.raw --fx NAME --p k=v`), exactly what PaintCraft's
test hook `cmd 995` prints (0 layer, 2 preview).  efftest: python build.py app efftest --out
build/a6 (the --efftest option chooses another binary).
"""
import pathlib, re, struct, subprocess, sys, zlib

HERE = pathlib.Path(__file__).resolve().parent
ROOT = HERE.parents[3]
W, H = 320, 240


def pixel(x, y):
    h = (x * 73856093 ^ y * 19349663) & 0xFFFFFFFF
    h = (h ^ (h >> 13)) * 0x5BD1E995 & 0xFFFFFFFF
    n = (h >> 24) - 128
    r = min(255, max(0, x * 255 // (W - 1) + n // 8))
    g = min(255, max(0, y * 255 // (H - 1) + n // 8))
    b = min(255, max(0, 128 + (x - y) // 3 + n // 6))
    a = 255
    if (x - 90) ** 2 + (y - 80) ** 2 < 40 ** 2:
        r, g, b = 250, 250, 245
    if 180 <= x < 290 and 150 <= y < 170:
        r, g, b = 20, 30, 40
    if 200 <= y < 220:
        a = 128
        if 40 <= x < 60:
            a = 0
    return (r, g, b, a)


def chunk(kind, data):
    c = struct.pack(">I", len(data)) + kind + data
    return c + struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)


def png(path):
    raw = bytearray()
    for y in range(H):
        raw.append(0)
        for x in range(W):
            raw += bytes(pixel(x, y))
    ihdr = struct.pack(">IIBBBBB", W, H, 8, 6, 0, 0, 0)
    data = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
    data += chunk(b"IDAT", zlib.compress(bytes(raw), 9)) + chunk(b"IEND", b"")
    path.write_bytes(data)


def fnv(data, h=0xcbf29ce484222325):
    for b in data:
        h = ((h ^ b) * 0x100000001b3) & 0xFFFFFFFFFFFFFFFF
    return h


def efftest_hash(fx, params, exe):
    out = ROOT / "build" / "a6_ref.raw"
    cmd = [str(exe), "--shot", "-", "--in", str(HERE / "a6_photo.png"), "--out", str(out), "--fx", fx]
    for k, v in params.items():
        cmd += ["--p", "%s=%s" % (k, v)]
    subprocess.run(cmd, cwd=ROOT, check=True, capture_output=True)
    d = out.read_bytes()
    _, w, h, _ = struct.unpack("<4sIII", d[:16])
    return "%016x" % fnv(d[16:16 + w * h * 4])


def fx_all(exe):
    """tests/fx_all.uis: every fx_map row of fx.s with a kernel, default parameters"""
    src = (ROOT / "apps/PaintCraft/src/fx.s").read_text(encoding="utf-8")
    ids = (ROOT / "apps/PaintCraft/inc/pn_ids.inc").read_text(encoding="utf-8")
    fxinc = (ROOT / "ASMLIB/inc/fx.inc").read_text(encoding="utf-8")
    cmdv = {m[0]: int(m[1]) for m in re.findall(r"^(CMD_\w+)\s*=\s*(\d+)", ids, re.M)}
    fxv = {m[0]: int(m[1]) for m in re.findall(r"^(FX_\w+)\s*=\s*(\d+)", fxinc, re.M)}
    lst = subprocess.run([str(exe), "--shot", "-", "--list"], cwd=ROOT, check=True,
                         capture_output=True, text=True).stdout
    names = {int(m[1]): (m[0], int(m[2])) for m in
             re.findall(r"^effect (\w+) id=(\d+) cat=\d+ flags=(\d+)", lst, re.M)}
    out = ["#!args --open apps/PaintCraft/tests/fixtures/a6_photo.png",
           "# fx_all.uis -- every registered effect from its menu row with its default parameters",
           "# (agent A6): the preview (dialog effects) or the committed layer (effects without a",
           "# dialog) equals efftest --fx NAME on a6_photo.png, bit-identical (FNV-1a 64, hook 995).",
           "# Generated by tests/fixtures/make_a6.py --fx-all; palette colours are the defaults",
           "# (black / white) like efftest's.",
           "size 1280 800", "theme light"]
    for cmd, fx, name in re.findall(r'FXMAP\s+(CMD_\w+),\s*(\w+),\s*"([^"]+)"', src):
        if fx == "0":
            continue
        key, flags = names[fxv[fx]]
        h = efftest_hash(key, {}, exe)
        out += ["# %s (%s)" % (name, key), "cmd %d" % cmdv[cmd]]
        if flags & 32:                                      # FXF_NO_DIALOG: applied at once
            out += ["cmd 995 0", 'expect #9990 text "%s"' % h, "key ctrl+z"]
        else:
            out += ["sync", "cmd 995 2", 'expect #9990 text "%s"' % h, "key esc",
                    "expect #9991 value 0"]
    out += ["cmd 995 0", 'expect #9990 text "%s"' % efftest_hash("levels", {}, exe)]
    (ROOT / "apps/PaintCraft/tests/fx_all.uis").write_text("\n".join(out) + "\n", encoding="utf-8",
                                                         newline="\n")


if __name__ == "__main__":
    exe = ROOT / "build/a6/win/efftest.exe"
    if "--efftest" in sys.argv:
        exe = pathlib.Path(sys.argv[sys.argv.index("--efftest") + 1])
    if "--hash" in sys.argv:
        i = sys.argv.index("--hash")
        params = dict(a.split("=", 1) for a in sys.argv[i + 2:] if "=" in a)
        print(efftest_hash(sys.argv[i + 1], params, exe))
    elif "--fx-all" in sys.argv:
        fx_all(exe)
    else:
        png(HERE / "a6_photo.png")
